'use strict';
(()=>{
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const trip=id=>TRIPS.find(t=>t.id===id);
 window.galleryMarkup=t=>{
  const photos=t.photos||[];if(!photos.length)return '';
  return `<section class="trip-gallery" data-gallery-root="${t.id}" aria-label="${escape(tr('A JOURNEY IN PICTURES'))}"><div class="gallery-collage ${photos.length<3?'gallery-small':''}">${photos.slice(0,3).map((m,i)=>`<button class="gallery-frame gallery-frame-${i}" data-gallery="${t.id}" data-photo="${i}" aria-label="${escape(tr('Open photograph {count}',{count:i+1}))}${i===0?' · '+escape(t.duration):''}">${photoHTML(m,'(max-width:700px) 60vw, 65vw',i?'loading="lazy"':'fetchpriority="high"')}${i===0?`<span class="gallery-duration">${escape(t.duration)}</span>`:''}</button>`).join('')}<button class="gallery-all" data-gallery="${t.id}" data-photo="0"><span aria-hidden="true">▦</span> ${escape(tr('View all photos'))} <small>${photos.length}</small></button></div><div class="gallery-under"><p><span class="eyebrow rust">${escape(tr('THE PLACES ALONG THE WAY'))}</span><span class="gallery-current-caption">${escape(photos[0].caption)}</span></p><div class="gallery-filmstrip" aria-label="${escape(tr('View gallery'))}">${photos.map((m,i)=>`<button data-gallery-select="${t.id}" data-photo="${i}" aria-label="${escape(tr('Open photograph {count}',{count:i+1}))}" aria-pressed="${i===0}">${photoHTML(m,'80px','loading="lazy"')}</button>`).join('')}</div></div></section>`;
 };
 window.cardGalleryControls=t=>(t.photos?.length>1?`<div class="card-gallery-controls"><button data-card-photo="${t.id}" data-step="-1" aria-label="${escape(tr('Previous photograph'))}">‹</button><button data-card-photo="${t.id}" data-step="1" aria-label="${escape(tr('Next photograph'))}">›</button></div><button class="card-photo-count" data-gallery="${t.id}" data-photo="0" aria-label="${escape(tr('View all photos'))}"><span aria-hidden="true">▦</span> <span data-card-counter aria-hidden="true">1 / ${t.photos.length}</span></button>`:'');
 const viewer=document.createElement('dialog');viewer.id='photo-viewer';viewer.className='photo-viewer';viewer.setAttribute('aria-labelledby','photo-viewer-title');
 viewer.innerHTML='<div class="photo-viewer-header"><div><p class="eyebrow">'+escape(tr('A JOURNEY IN PICTURES'))+'</p><h2 id="photo-viewer-title"></h2></div><button class="viewer-close" data-gallery-close aria-label="'+escape(tr('Close gallery'))+'">×</button></div><div class="photo-viewer-stage"><button class="viewer-arrow viewer-prev" data-lightbox-step="-1" aria-label="'+escape(tr('Previous photograph'))+'">‹</button><figure><img id="lightbox-image" alt=""><figcaption id="lightbox-caption"></figcaption></figure><button class="viewer-arrow viewer-next" data-lightbox-step="1" aria-label="'+escape(tr('Next photograph'))+'">›</button></div><div class="photo-viewer-bottom"><p id="lightbox-count" aria-live="polite"></p><div id="lightbox-thumbs" class="lightbox-thumbs"></div><p class="gallery-disclaimer">'+escape(tr('Destination photographs illustrate the region. Final venues and services are agreed separately.'))+'</p></div>';
 document.body.append(viewer);let activeTrip=null,index=0,touchX=null;
 function show(indexRequested){if(!activeTrip)return;const photos=activeTrip.photos;index=(indexRequested+photos.length)%photos.length;const m=photos[index],image=viewer.querySelector('#lightbox-image');image.src=m.path;image.alt=m.alt;viewer.querySelector('#lightbox-caption').innerHTML=escape(m.caption);viewer.querySelector('#lightbox-count').textContent=tr('Photograph {count} of {total}',{count:index+1,total:photos.length});viewer.querySelectorAll('[data-lightbox-photo]').forEach(b=>{b.setAttribute('aria-pressed',String(+b.dataset.lightboxPhoto===index))});viewer.querySelector('[data-lightbox-photo="'+index+'"]')?.scrollIntoView({block:'nearest',inline:'nearest'});}
 window.openGallery=(id,start=0)=>{activeTrip=trip(id);if(!activeTrip?.photos?.length)return;viewer.querySelector('#photo-viewer-title').textContent=activeTrip.title;viewer.querySelector('#lightbox-thumbs').innerHTML=activeTrip.photos.map((m,i)=>`<button data-lightbox-photo="${i}" aria-label="${escape(tr('Open photograph {count}',{count:i+1}))}" aria-pressed="false">${photoHTML(m,'100px','loading="lazy"')}</button>`).join('');if(!viewer.open)viewer.showModal();show(start);viewer.querySelectorAll('[data-lightbox-step]').forEach(b=>b.hidden=activeTrip.photos.length<2)};
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.gallery){e.preventDefault();openGallery(b.dataset.gallery,+b.dataset.photo||0)}else if(b.dataset.gallerySelect){const t=trip(b.dataset.gallerySelect),m=t.photos[+b.dataset.photo],root=b.closest('[data-gallery-root]'),frame=root.querySelector('.gallery-frame-0');root.querySelectorAll('.gallery-frame').forEach((el,offset)=>{const n=(+b.dataset.photo+offset)%t.photos.length,picture=t.photos[n];el.querySelector('img').src=picture.path;el.querySelector('img').alt=picture.alt;el.dataset.photo=n;el.setAttribute('aria-label',tr('Open photograph {count}',{count:n+1})+(offset===0?' · '+t.duration:''))});root.querySelector('.gallery-all').dataset.photo=b.dataset.photo;root.querySelector('.gallery-current-caption').textContent=m.caption;root.querySelectorAll('[data-gallery-select]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)))}else if(b.dataset.cardPhoto){const t=trip(b.dataset.cardPhoto),card=b.closest('.trip-card'),n=((+card.dataset.photoIndex||0)+(+b.dataset.step)+t.photos.length)%t.photos.length,m=t.photos[n];card.dataset.photoIndex=n;const image=card.querySelector('.card-image-wrap>a>img');image.src=m.path;image.alt=m.alt;card.querySelector('[data-card-counter]').textContent=(n+1)+' / '+t.photos.length;card.querySelector('[data-gallery]').dataset.photo=n}else if(b.hasAttribute('data-gallery-close'))viewer.close();else if(b.dataset.lightboxStep)show(index+(+b.dataset.lightboxStep));else if(b.dataset.lightboxPhoto!==undefined)show(+b.dataset.lightboxPhoto)});
 viewer.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1))}});
 viewer.querySelector('figure').addEventListener('pointerdown',e=>{touchX=e.clientX});viewer.querySelector('figure').addEventListener('pointerup',e=>{if(touchX!==null&&Math.abs(e.clientX-touchX)>45)show(index+(e.clientX<touchX?1:-1));touchX=null});
})();
